labs.solution:
def affine_batch(x, weight, bias):
    if not x or not weight or not x[0]:
        raise ValueError("矩阵必须非空")
    dimension = len(x[0])
    if any(len(row) != dimension for row in x + weight):
        raise ValueError("输入和权重的特征维必须相同")
    if len(bias) != len(weight):
        raise ValueError("每个输出需要一个偏置")
    return [[sum(value * coefficient for value, coefficient in zip(row, w)) + b
             for w, b in zip(weight, bias)] for row in x]

def parameter_count(widths):
    if len(widths) < 2 or any(type(n) is not int or n <= 0 for n in widths):
        raise ValueError("至少需要输入、输出两个正整数维度")
    return sum(before * after + after for before, after in zip(widths, widths[1:]))

