labs.solution:
import torch
from torch import nn

class MaskedMeanHead(nn.Module):
    def __init__(self, input_dim, hidden_dim, output_dim):
        super().__init__()
        self.network = nn.Sequential(nn.Linear(input_dim, hidden_dim), nn.GELU(),
                                     nn.Linear(hidden_dim, output_dim))

    def forward(self, tokens, mask):
        if tokens.ndim != 3 or mask.dtype != torch.bool or mask.shape != tokens.shape[:2]:
            raise ValueError("需要 B,T,D 输入与 bool B,T Mask")
        counts = mask.sum(dim=1, keepdim=True)
        if (counts == 0).any():
            raise ValueError("存在没有有效 token 的样本")
        clean = tokens.masked_fill(~mask[..., None], 0)
        pooled = clean.sum(dim=1) / counts
        return self.network(pooled)

