def prefix_action_mask(prefix_len, action_len, mode="denoise"):
    if not isinstance(prefix_len, int) or not isinstance(action_len, int):
        raise ValueError("lengths must be integers")
    if prefix_len < 0 or action_len < 1:
        raise ValueError("need prefix_len >= 0 and action_len >= 1")
    if mode not in ("denoise", "causal"):
        raise ValueError("unknown action visibility")
    total = prefix_len + action_len
    allowed = []
    for i in range(total):
        row = []
        for j in range(total):
            if i < prefix_len:
                visible = j < prefix_len
            else:
                visible = j < prefix_len or mode == "denoise" or j <= i
            row.append(visible)
        allowed.append(row)
    return allowed

import math
import torch

def rotary_pairs(x, positions, base=10000.0):
    if x.ndim != 4 or x.shape[-1] < 2 or x.shape[-1] % 2:
        raise ValueError("x must be [B,H,T,even_dh]")
    if positions.ndim != 1 or len(positions) != x.shape[-2]:
        raise ValueError("positions must have one entry per token")
    if not math.isfinite(base) or base <= 0:
        raise ValueError("base must be finite and positive")
    freq = base ** (-torch.arange(0, x.shape[-1], 2,
                                  device=x.device, dtype=x.dtype) / x.shape[-1])
    angle = positions.to(device=x.device, dtype=x.dtype)[:, None] * freq[None, :]
    cos, sin = angle.cos()[None, None], angle.sin()[None, None]
    even, odd = x[..., 0::2], x[..., 1::2]
    return torch.stack((even*cos - odd*sin, even*sin + odd*cos), -1).flatten(-2)

import math

def linear_path(noise, data, t):
    if not noise or len(noise) != len(data) or not 0 <= t <= 1:
        raise ValueError("需要同长非空端点以及 [0,1] 时间")
    if not all(math.isfinite(x) for x in [*noise, *data, t]):
        raise ValueError("输入必须有限")
    xt = [(1-t)*a+t*b for a,b in zip(noise,data)]
    velocity = [b-a for a,b in zip(noise,data)]
    return xt, velocity

def conditional_mean_velocity(velocities, weights):
    if not velocities or len(velocities) != len(weights):
        raise ValueError("配对数量不一致")
    dim = len(velocities[0])
    if dim == 0 or any(len(v) != dim for v in velocities):
        raise ValueError("速度维度不一致")
    if any(w < 0 or not math.isfinite(w) for w in weights) or sum(weights) <= 0:
        raise ValueError("需要非负权重和正总权重")
    if not all(math.isfinite(x) for v in velocities for x in v):
        raise ValueError("速度必须有限")
    total = sum(weights)
    return [sum(w*v[d] for w,v in zip(weights,velocities))/total for d in range(dim)]

